import { cache } from 'react';

async function Header() {
  const getCustomer = cache(fetchCurrentCustomer);
  const customer = await getCustomer();
  return <AccountMenu name={customer?.name ?? null} />;
}

async function PriceBox() {
  const getCustomer = cache(fetchCurrentCustomer);
  const customer = await getCustomer();
  return <Price tier={customer?.loyaltyTier ?? 'standard'} />;
}

'use client';

export function CartBadge() {
  const count = typeof window === 'undefined' ? 0 : readCartCount(window.localStorage);
  return <span aria-label="Items in cart">{count}</span>;
}

import { cacheLife } from 'next/cache';

export async function getCustomerPrice(productId: string): Promise<number> {
  'use cache';
  cacheLife('hours');
  const customer = await getCurrentCustomer(); // reads cookies() inside
  return ordersApi.getPrice(productId, customer?.id ?? null);
}

'use server';

export async function cancelOrder(orderId: string): Promise<void> {
  const customer = await getCurrentCustomer();
  if (customer === null) {
    throw new Error('Unauthorized');
  }
  await ordersApi.cancel(orderId);
  updateTag('orders-' + customer.id);
}

